package tv.moonga.classicworlds;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.*;
import net.runelite.api.*;
import net.runelite.api.events.ClientTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.WorldUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.KeyListener;

@PluginDescriptor(name="Classic World Selector",description="Restore the compact classic login world grid",tags={"world","login","classic","region"})
public class ClassicWorldSelectorPlugin extends Plugin {
  @Inject private Client client;
  @Inject private ClientThread clientThread;
  @Inject private WorldService worldService;
  @Inject private ScheduledExecutorService executor;
  @Inject private ClassicWorldSelectorConfig config;
  @Inject private ConfigManager configManager;
  @Inject private KeyManager keyManager;
  @Inject private net.runelite.client.eventbus.EventBus eventBus;
  private ClassicWorldPanel panel;
  private ClassicWorldButton button;
  private JLayeredPane layer;
  private javax.swing.Timer timer;
  private volatile boolean running,opened;
  private volatile List<WorldEntry> serviceWorlds=Collections.emptyList();
  private final java.util.concurrent.atomic.AtomicBoolean refreshing=new java.util.concurrent.atomic.AtomicBoolean();
  private boolean assetsLoaded;
  private int ticks;
  private volatile Map<Integer,WorldEntry> knownWorlds=Collections.emptyMap();
  private WorldPreferences currentPreferences=WorldPreferences.DEFAULT;
  private final KeyListener selectorKeys=new KeyListener(){
    @Override public boolean isEnabledOnLoginScreen(){return true;}
    @Override public void keyPressed(KeyEvent event){
      if(!selectorInputActive())return;
      event.consume();
      int key=event.getKeyCode(),modifiers=event.getModifiersEx();
      SwingUtilities.invokeLater(()->{if(selectorInputActive()&&panel!=null)panel.handleKey(key,modifiers);});
    }
    @Override public void keyReleased(KeyEvent event){if(selectorInputActive())event.consume();}
    @Override public void keyTyped(KeyEvent event){
      if(!selectorInputActive())return;event.consume();char value=event.getKeyChar();
      SwingUtilities.invokeLater(()->{if(selectorInputActive()&&panel!=null)panel.handleTyped(value);});
    }
  };
  private boolean selectorInputActive(){return running&&opened&&canSelect(client.getGameState());}

  @Override protected void startUp(){
    running=true;
    keyManager.registerKeyListener(selectorKeys);
    SwingUtilities.invokeLater(()->{
      if(!running)return;
      panel=new ClassicWorldPanel(this::select,this::close);
      button=new ClassicWorldButton(this::open);button.world(client.getWorld());
      panel.preferencesChanged(this::savePreference);
      panel.settingsRequested(this::openSettings);
      applyDisplaySize();
      panel.setVisible(false);timer=new javax.swing.Timer(100,e->position());timer.start();position();
      clientThread.invokeLater(()->{if(running)sample();});
    });
    refreshWorlds();
  }
  static boolean canSelect(GameState state){return state==GameState.LOGIN_SCREEN;}
  @Provides ClassicWorldSelectorConfig provideConfig(ConfigManager manager){return manager.getConfig(ClassicWorldSelectorConfig.class);}
  @Subscribe public void onConfigChanged(ConfigChanged event){
    if(ClassicWorldSelectorConfig.GROUP.equals(event.getGroup()))SwingUtilities.invokeLater(()->{if(running&&panel!=null){applyDisplaySize();position();}});
  }
  private void applyDisplaySize(){
    DisplaySize size=config==null?DisplaySize.NORMAL:config.displaySize();
    panel.displaySize(size);
    currentPreferences=WorldPreferences.from(config);panel.options(currentPreferences);button.options(currentPreferences);
  }
  private void savePreference(String key,Object value){
    // Apply to the visible button immediately, independently of ConfigChanged dispatch timing.
    if(!key.equals("displaySize")){currentPreferences=currentPreferences.with(key,value);button.options(currentPreferences);}
    configManager.setConfiguration(ClassicWorldSelectorConfig.GROUP,key,value);
  }
  @Subscribe public void onClientTick(ClientTick event){if(running&&++ticks%50==0&&canSelect(client.getGameState()))sample();}
  private void sample(){
    if(!running)return;
    List<WorldEntry> snapshot=new ArrayList<>();
    net.runelite.api.World[] nativeWorlds=client.getWorldList();
    if(nativeWorlds!=null&&nativeWorlds.length>0){for(net.runelite.api.World w:nativeWorlds)if(w!=null)snapshot.add(WorldEntry.from(w));}
    else snapshot.addAll(serviceWorlds);
    EnumComposition locations=canSelect(client.getGameState())?client.getEnum(EnumID.WORLD_LOCATIONS):null;
    for(int i=0;i<snapshot.size();i++){
      WorldEntry world=snapshot.get(i);
      if(locations!=null)snapshot.set(i,world.withServerLocation(locations.getIntValue(world.id)));
    }
    if(!assetsLoaded&&client.getIndexSprites()!=null){
      BufferedImage[] bg=images(814),flags=images(815),stars=images(817),arrows=images(816);
      BufferedImage[] left=images(308),right=images(309),worldButton=images(818);
      ClientBitmapFont small=font(494),bold=font(496);
      assetsLoaded=bg!=null&&flags!=null&&stars!=null&&arrows!=null&&first(left)!=null&&first(right)!=null&&first(worldButton)!=null&&small!=null&&bold!=null;
      SwingUtilities.invokeLater(()->{if(running&&panel!=null){panel.assets(bg,flags,stars,arrows);panel.pageArrows(first(left),first(right));panel.fonts(small,bold);button.background(first(worldButton));button.fonts(small,bold);button.flagSprites(flags);}});
    }
    Map<Integer,WorldEntry> worldMap=new HashMap<>();for(WorldEntry world:snapshot)worldMap.put(world.id,world);knownWorlds=Collections.unmodifiableMap(worldMap);
    SwingUtilities.invokeLater(()->{if(running&&panel!=null)panel.worlds(snapshot);});
  }
  private static BufferedImage first(BufferedImage[] images){return images==null||images.length==0?null:images[0];}
  private ClientBitmapFont font(int archive){
    IndexDataBase metrics=client.getIndex(13);if(metrics==null)return null;
    byte[] data=metrics.loadData(archive,0);if(data==null)return null;
    return ClientBitmapFont.from(data,client.getSprites(client.getIndexSprites(),archive,0));
  }
  private void refreshWorlds(){
    if(!refreshing.compareAndSet(false,true))return;
    executor.execute(()->{
      try{
        if(!running)return;
        // WorldService can wait for its first HTTP result. Never call it on the game thread.
        worldService.refresh();
        net.runelite.http.api.worlds.WorldResult result=worldService.getWorlds();
        List<WorldEntry> values=new ArrayList<>();
        if(result!=null&&result.getWorlds()!=null)for(net.runelite.http.api.worlds.World w:result.getWorlds())
          values.add(new WorldEntry(w.getId(),w.getPlayers(),w.getRegion()==null?0:w.getRegion().getId(),w.getActivity(),w.getAddress(),WorldUtil.toWorldTypes(w.getTypes())));
        if(running){serviceWorlds=Collections.unmodifiableList(values);clientThread.invokeLater(()->{if(running)sample();});}
      }catch(RuntimeException error){
        org.slf4j.LoggerFactory.getLogger(getClass()).warn("Could not refresh the classic world list",error);
        SwingUtilities.invokeLater(()->{if(running&&panel!=null)panel.status("World list unavailable. Close and reopen to retry.");});
      }finally{refreshing.set(false);}
    });
  }
  private BufferedImage[] images(int archive){
    try{
      SpritePixels[] sprites=client.getSprites(client.getIndexSprites(),archive,0);
      if(sprites==null)return null;
      BufferedImage[] images=new BufferedImage[sprites.length];
      for(int i=0;i<sprites.length;i++)if(sprites[i]!=null){
        SpritePixels sprite=sprites[i];
        // Native drawAt includes the transparent canvas and sprite offsets.
        BufferedImage image=new BufferedImage(Math.max(sprite.getMaxWidth(),sprite.getWidth()+sprite.getOffsetX()),Math.max(sprite.getMaxHeight(),sprite.getHeight()+sprite.getOffsetY()),BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=image.createGraphics();try{g.drawImage(sprite.toBufferedImage(),sprite.getOffsetX(),sprite.getOffsetY(),null);}finally{g.dispose();}
        images[i]=image;
      }
      return images;
    }catch(RuntimeException e){return null;}
  }
  private void open(){
    if(!running||!canSelect(client.getGameState()))return;
    opened=true;position();clientThread.invokeLater(()->{if(running)sample();});refreshWorlds();
  }
  void openSettings(){
    if(!selectorInputActive())return;
    // Keep the grid open; native sidebar controls receive their own focus and keys.
    // Use the same public configuration event handled by RuneLite's ConfigPlugin.
    net.runelite.client.ui.overlay.Overlay settingsTarget=new net.runelite.client.ui.overlay.Overlay(this){
      @Override public Dimension render(Graphics2D graphics){return null;}
    };
    eventBus.post(new net.runelite.client.events.OverlayMenuClicked(
        new net.runelite.client.ui.overlay.OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG,"Configure","Classic World Selector"),settingsTarget));
  }
  private void close(){opened=false;if(panel!=null)panel.busy(false);position();}
  private void position(){
    if(panel==null||button==null)return;
    Canvas canvas=client.getCanvas();JRootPane root=SwingUtilities.getRootPane(canvas);
    if(root==null){panel.setVisible(false);button.setVisible(false);return;}
    if(layer!=root.getLayeredPane()){
      if(layer!=null){layer.remove(panel);layer.remove(button);}
      layer=root.getLayeredPane();layer.add(button,JLayeredPane.PALETTE_LAYER);layer.add(panel,JLayeredPane.POPUP_LAYER);
    }
    java.awt.Point origin=SwingUtilities.convertPoint(canvas,0,0,layer);
    boolean login=running&&canSelect(client.getGameState());if(!login)opened=false;
    panel.setBounds(origin.x,origin.y,canvas.getWidth(),canvas.getHeight());panel.setVisible(login&&opened);
    Dimension size=button.getPreferredSize();
    button.setBounds(origin.x+Math.max(0,(canvas.getWidth()-765)/2)+5,origin.y+498-size.height,size.width,size.height);
    button.world(client.getWorld());button.setVisible(login&&!opened);
    WorldEntry current=knownWorlds.get(client.getWorld());
    button.worldInfo(current==null?-1:current.location,current==null?client.getWorldType():current.types,current==null?"-":current.activity);
  }
  private void select(WorldEntry entry){
    if(!entry.selectable())return;panel.busy(true);
    clientThread.invokeLater(()->{
      if(!running)return;
      if(!canSelect(client.getGameState())){SwingUtilities.invokeLater(()->{if(running)close();});return;}
      try{
        net.runelite.api.World world=client.createWorld();
        world.setId(entry.id);world.setAddress(entry.address);world.setActivity(entry.activity);
        world.setLocation(entry.location);world.setPlayerCount(entry.players);world.setTypes(entry.types.clone());
        client.changeWorld(world);
        SwingUtilities.invokeLater(()->{if(running)close();});
      }catch(RuntimeException error){SwingUtilities.invokeLater(()->{if(running){panel.busy(false);panel.status("Could not select this world. Please try again.");}});}
    });
  }
  @Override protected void shutDown(){
    running=false;opened=false;
    keyManager.unregisterKeyListener(selectorKeys);
    SwingUtilities.invokeLater(()->{if(timer!=null)timer.stop();if(layer!=null){if(panel!=null)layer.remove(panel);if(button!=null)layer.remove(button);layer.revalidate();layer.repaint();}panel=null;button=null;});
  }
}

package tv.moonga.classicworlds;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.*;
import net.runelite.api.SpritePixels;

/** The client's own glyph masks, offsets, advances and baseline, without TrueType substitution. */
final class ClientBitmapFont {
  static final class Glyph {
    final int width,height,x,y;
    final int[] mask;
    Glyph(int width,int height,int x,int y,int[] pixels){
      this.width=width;this.height=height;this.x=x;this.y=y;this.mask=pixels.clone();
    }
  }
  private final Glyph[] glyphs;
  private final int[] advances=new int[256];
  final int ascent;
  private final Map<Integer,BufferedImage[]> colours=new HashMap<>();
  ClientBitmapFont(byte[] metrics,Glyph[] glyphs){
    if(metrics==null||metrics.length!=257||glyphs==null||glyphs.length!=256)
      throw new IllegalArgumentException("Unsupported client bitmap font");
    for(int i=0;i<256;i++)advances[i]=metrics[i]&255;
    ascent=metrics[256]&255;this.glyphs=glyphs.clone();
  }
  static ClientBitmapFont from(byte[] metrics,SpritePixels[] sprites){
    if(metrics==null||sprites==null||sprites.length!=256)return null;
    Glyph[] glyphs=new Glyph[256];
    for(int i=0;i<256;i++){
      SpritePixels s=sprites[i];if(s==null)return null;
      glyphs[i]=new Glyph(s.getWidth(),s.getHeight(),s.getOffsetX(),s.getOffsetY(),s.getPixels());
    }
    return new ClientBitmapFont(metrics,glyphs);
  }
  int width(String text){int width=0;for(int i=0;i<text.length();i++)width+=advances[code(text.charAt(i))];return width;}
  void center(Graphics2D g,String text,int x,int baseline,int colour,int shadow){draw(g,text,x-width(text)/2,baseline,colour,shadow);}
  void draw(Graphics2D g,String text,int x,int baseline,int colour,int shadow){
    if(shadow>=0)draw(g,text,x+1,baseline+1,shadow,-1);
    BufferedImage[] images=colours.computeIfAbsent(colour,c->new BufferedImage[256]);
    for(int i=0;i<text.length();i++){
      int code=code(text.charAt(i));Glyph glyph=glyphs[code];
      if(code!=32&&glyph!=null&&glyph.width>0&&glyph.height>0){
        BufferedImage image=images[code];
        if(image==null){
          image=new BufferedImage(glyph.width,glyph.height,BufferedImage.TYPE_INT_ARGB);
          int[] pixels=new int[glyph.mask.length];for(int j=0;j<pixels.length;j++)if(glyph.mask[j]!=0)pixels[j]=0xff000000|(colour&0xffffff);
          image.setRGB(0,0,glyph.width,glyph.height,pixels,0,glyph.width);images[code]=image;
        }
        g.drawImage(image,x+glyph.x,baseline-ascent+glyph.y,null);
      }
      x+=advances[code];
    }
  }
  private static int code(char c){
    if(c==160)return 32;
    if(c>0&&c<128||c>=160&&c<=255)return c;
    String special="€\u0000‚ƒ„…†‡ˆ‰Š‹Œ\u0000Ž\u0000\u0000‘’“”•–—˜™š›œ\u0000žŸ";
    int at=special.indexOf(c);return at<0?63:128+at;
  }
}

package tv.moonga.classicworlds;

public enum DisplaySize {
  NORMAL("Normal",1),LARGER("Large",1.15),EXTRA_LARGE("Extra large",1.3);
  final double factor;
  private final String label;
  DisplaySize(String label,double factor){this.label=label;this.factor=factor;}
  @Override public String toString(){return label;}
}

package tv.moonga.classicworlds;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.awt.geom.*;

/** Rasterise game-style text before Windows DPI scaling, then preserve its pixel edges. */
final class PixelDrawing {
  static Graphics2D raster(BufferedImage image){
    Graphics2D g=image.createGraphics();
    g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_OFF);
    g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
    g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS,RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
    g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
    return g;
  }
  static void blit(Graphics graphics,BufferedImage image,int x,int y,int width,int height){
    Graphics2D g=(Graphics2D)graphics.create();
    try{
      g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
      g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_OFF);
      g.drawImage(image,x,y,width,height,null);
    }finally{g.dispose();}
  }
  /** Preserve the original DPI scale; enlargement is an explicit user preference. */
  static final class DeviceGrid {
    final AffineTransform transform;
    final double scale;
    DeviceGrid(Graphics graphics){this(graphics,DisplaySize.NORMAL);}
    DeviceGrid(Graphics graphics,DisplaySize size){
      transform=((Graphics2D)graphics).getTransform();
      scale=Math.hypot(transform.getScaleX(),transform.getShearY())*size.factor;
    }
    Point point(double x,double y){
      Point2D p=transform.transform(new Point2D.Double(x,y),null);
      return new Point((int)Math.round(p.getX()),(int)Math.round(p.getY()));
    }
    void draw(Graphics graphics,BufferedImage image,int deviceX,int deviceY){
      Graphics2D g=(Graphics2D)graphics.create();
      try{
        Shape clip=g.getClip();Shape deviceClip=clip==null?null:transform.createTransformedShape(clip);
        g.setTransform(new AffineTransform());if(deviceClip!=null)g.setClip(deviceClip);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(image,deviceX,deviceY,(int)Math.round(image.getWidth()*scale),(int)Math.round(image.getHeight()*scale),null);
      }finally{g.dispose();}
    }
    void centered(Graphics graphics,BufferedImage image,double x,double y){
      Point center=point(x,y);draw(graphics,image,center.x-(int)Math.round(image.getWidth()*scale)/2,center.y-(int)Math.round(image.getHeight()*scale)/2);
    }
  }
}

package tv.moonga.classicworlds;

import java.util.EnumSet;
import net.runelite.api.World;
import net.runelite.api.WorldType;

final class WorldEntry {
  final int id, players, location;
  final String activity, address;
  final EnumSet<WorldType> types;
  final int serverLocation;

  WorldEntry(int id, int players, int location, String activity, String address, EnumSet<WorldType> types) {
    this(id,players,location,activity,address,types,0);
  }
  WorldEntry(int id,int players,int location,String activity,String address,EnumSet<WorldType> types,int serverLocation) {
    this.id=id; this.players=players; this.location=location;
    this.activity=activity==null?"-":activity; this.address=address;
    this.types=types.clone();
    this.serverLocation=serverLocation;
  }
  WorldEntry withServerLocation(int value){return new WorldEntry(id,players,location,activity,address,types,value);}
  static WorldEntry from(World w) {
    return new WorldEntry(w.getId(),w.getPlayerCount(),w.getLocation(),w.getActivity(),w.getAddress(),w.getTypes());
  }
  boolean members() { return types.contains(WorldType.MEMBERS); }
  boolean selectable() { return players>=0 && players<=1980 && address!=null && !address.isBlank(); }
  String population() { return players<0?"OFF":players>1980?"FULL":Integer.toString(players); }
  String typeLabel() {
    if(types.contains(WorldType.DEADMAN))return "Deadman";
    if(types.contains(WorldType.HARDCORE_MAIN))return "Hardcore";
    if(types.contains(WorldType.PVP))return "PvP";
    if(types.contains(WorldType.HIGH_RISK))return "High Risk";
    if(types.contains(WorldType.BETA_WORLD))return "Beta";
    if(types.contains(WorldType.QUEST_SPEEDRUNNING))return "Speedrunning";
    if(types.contains(WorldType.SKILL_TOTAL))return "Skill total";
    return members()?"Members":"Free";
  }
  int background() {
    int base=0;
    if(types.contains(WorldType.HARDCORE_MAIN))base=16;
    else if(types.contains(WorldType.PVP))base=2;
    else if(types.contains(WorldType.DEADMAN))base=4;
    else if(types.contains(WorldType.BETA_WORLD))base=6;
    else if(types.contains(WorldType.SEASONAL))base=8;
    else if(types.contains(WorldType.HIGH_RISK))base=10;
    else if(types.contains(WorldType.QUEST_SPEEDRUNNING))base=12;
    return base+(members()?1:0);
  }
  String tooltip() {
    String risk=types.contains(WorldType.PVP)||types.contains(WorldType.HIGH_RISK)||types.contains(WorldType.DEADMAN)
        ?" — "+typeLabel():"";
    return (activity.equals("-")?typeLabel():activity)+risk;
  }
}

package tv.moonga.classicworlds;

import java.awt.*;
import java.util.function.BiConsumer;

/** Bitmap dropdowns share the selector's surface, avoiding heavyweight-canvas popup clipping. */
final class WorldMenus {
  private static final Rectangle[] BUTTONS={new Rectangle(178,27,145,23),new Rectangle(328,27,140,23),new Rectangle(473,27,148,23),new Rectangle(626,27,102,23)};
  static final Rectangle SETTINGS=new Rectangle(733,27,24,23);
  private final Runnable openSettings;
  static final int DISMISS=-199;
  private final BiConsumer<String,Object> changed;
  private WorldPreferences options=WorldPreferences.DEFAULT;
  private DisplaySize textSize=DisplaySize.NORMAL;
  private int open=-1,keyboardRow=-1;
  private Point mouse=new Point(-1,-1);
  WorldMenus(BiConsumer<String,Object> changed){this(changed,()->{});}
  WorldMenus(BiConsumer<String,Object> changed,Runnable openSettings){this.changed=changed;this.openSettings=openSettings;}
  void settings(WorldPreferences value,DisplaySize size){options=value;textSize=size;}
  boolean isOpen(){return open>=0;}
  boolean dismiss(){if(open<0)return false;open=-1;keyboardRow=-1;return true;}
  void mouse(Point point){mouse=point;keyboardRow=-1;}
  private Object[] values(){
    switch(open){case 0:return WorldPreferences.GameMode.values();case 1:return WorldPreferences.Region.values();case 2:return WorldPreferences.Membership.values();default:return new Boolean[]{true,false};}
  }
  Rectangle menuBounds(){
    if(open<0)return new Rectangle();
    int width=Math.max(BUTTONS[open].width,180);
    return new Rectangle(Math.min(BUTTONS[open].x,765-width-4),52,width,values().length*20+2);
  }
  Integer hit(Point p){
    if(open>=0){Rectangle menu=menuBounds();if(menu.contains(p)){
      int row=(p.y-menu.y-1)/20;return row>=0&&row<values().length?-2000-row:DISMISS;
    }}
    if(SETTINGS.contains(p))return -104;
    for(int i=0;i<BUTTONS.length;i++)if(BUTTONS[i].contains(p))return -100-i;
    return open>=0?DISMISS:null;
  }
  boolean activate(int target){
    if(target==DISMISS){dismiss();return true;}
    if(target==-104){dismiss();openSettings.run();return true;}
    if(target<=-100&&target>=-103){int next=-target-100;open=open==next?-1:next;keyboardRow=-1;return true;}
    if(target<=-2000&&target>=-2100&&open>=0){
      int row=-target-2000;Object[] values=values();if(row>=values.length)return true;
      int selectedMenu=open;Object value=values[row];dismiss();
      if(selectedMenu==0)changed.accept("preferredMode",value);
      else if(selectedMenu==1)changed.accept("preferredRegion",value);
      else if(selectedMenu==2)changed.accept("membership",value);
      else if(selectedMenu==3)changed.accept("compact",value);
      return true;
    }
    return false;
  }
  void step(int direction){if(open>=0)keyboardRow=keyboardRow<0?(direction<0?values().length-1:0):Math.floorMod(keyboardRow+direction,values().length);}
  void choose(){if(open>=0&&keyboardRow>=0)activate(-2000-keyboardRow);}
  private String label(int row){
    if(open==3)return row==0?"Compact":"With activity";
    return values()[row].toString();
  }
  private boolean selected(int row){
    Object value=values()[row];
    switch(open){case 0:return value==options.mode;case 1:return value==options.region;case 2:return value==options.membership;case 3:return (Boolean)value==options.compact;default:return false;}
  }
  void paint(Graphics2D g,ClientBitmapFont font){
    g.setColor(new Color(0x171719));g.fillRect(0,23,765,32);
    String[] labels={"Mode: "+options.mode,"Region: "+options.region,"Membership: "+options.membership,"View: "+(options.compact?"Compact":"Activity")};
    for(int i=0;i<BUTTONS.length;i++){
      Rectangle r=BUTTONS[i];g.setColor(new Color(open==i?0x48453a:0x303034));g.fillRect(r.x,r.y,r.width,r.height);
      g.setColor(new Color(0x857f68));g.drawRect(r.x,r.y,r.width-1,r.height-1);
      Shape clip=g.getClip();g.clipRect(r.x+5,r.y+2,r.width-22,r.height-4);
      if(font!=null)font.draw(g,labels[i],r.x+6,r.y+15,0xffffff,-1);g.setClip(clip);
      g.setColor(new Color(0xd7c580));g.fillPolygon(new int[]{r.x+r.width-15,r.x+r.width-7,r.x+r.width-11},new int[]{r.y+9,r.y+9,r.y+14},3);
    }
    Rectangle cog=SETTINGS;boolean hoveredCog=cog.contains(mouse);
    g.setColor(new Color(hoveredCog?0x48453a:0x303034));g.fillRect(cog.x,cog.y,cog.width,cog.height);
    g.setColor(new Color(0x857f68));g.drawRect(cog.x,cog.y,cog.width-1,cog.height-1);
    // A rasterised eight-tooth gear stays sharp alongside the client glyphs.
    int cx=cog.x+12,cy=cog.y+11;g.setColor(new Color(hoveredCog?0xffdf83:0xd7c580));
    g.fillOval(cx-6,cy-6,13,13);
    for(int tooth=0;tooth<8;tooth++){double angle=tooth*Math.PI/4;int x=cx+(int)Math.round(Math.cos(angle)*7),y=cy+(int)Math.round(Math.sin(angle)*7);g.fillRect(x-1,y-1,3,3);}
    g.setColor(new Color(0x303034));g.fillOval(cx-3,cy-3,7,7);
    if(open<0)return;
    Rectangle r=menuBounds();g.setColor(new Color(0x252527));g.fillRect(r.x,r.y,r.width,r.height);g.setColor(new Color(0xb1a078));g.drawRect(r.x,r.y,r.width-1,r.height-1);
    Integer target=hit(mouse);int hovered=keyboardRow>=0?keyboardRow:target!=null&&target<=-2000?-target-2000:-1;
    for(int row=0;row<values().length;row++){
      int y=r.y+1+row*20;if(row==hovered){g.setColor(new Color(0x514b36));g.fillRect(r.x+1,y,r.width-2,20);}
      if(font!=null)font.draw(g,label(row),r.x+7,y+14,selected(row)?0xffff00:0xffffff,-1);
    }
  }
}

package tv.moonga.classicworlds;

import java.util.*;
import net.runelite.api.WorldType;

/** Shared state for on-screen menus, persisted RuneLite settings and world ordering. */
public final class WorldPreferences {
  public enum GameMode {
    ALL("All modes"),MAIN_GAME("Main game"),PVP("Main game (PvP)"),HARDCORE("Hardcore"),DEADMAN("Deadman (Perm.)"),SPEEDRUNNING("Speedrunning");
    final String label;GameMode(String label){this.label=label;}@Override public String toString(){return label;}
    static GameMode of(EnumSet<WorldType> types){
      if(types.contains(WorldType.HARDCORE_MAIN))return HARDCORE;
      if(types.contains(WorldType.DEADMAN))return DEADMAN;
      if(types.contains(WorldType.QUEST_SPEEDRUNNING))return SPEEDRUNNING;
      return types.contains(WorldType.PVP)?PVP:MAIN_GAME;
    }
  }
  public enum Region {
    ALL("All regions",-1),USA("United States",0),USA_EAST("USA East",0),USA_WEST("USA West",0),UK("United Kingdom",1),AUSTRALIA("Australia",3),GERMANY("Germany",7),BRAZIL("Brazil",8),SINGAPORE("Singapore",10),SOUTH_AFRICA("South Africa",12),JAPAN("Japan",9),USA_EAST_WEST("USA East + West",0),USA_WEST_EAST("USA West + East",0);
    final String label;final int id;Region(String label,int id){this.label=label;this.id=id;}@Override public String toString(){return label;}
    int rank(WorldEntry world){
      if(this==ALL)return 0;
      // These WORLD_LOCATIONS values are also used by RuneLite's World Hopper.
      boolean east=world.location==0&&world.serverLocation==-42;
      boolean west=world.location==0&&world.serverLocation==-73;
      switch(this){
        case USA_EAST:return east?0:1;
        case USA_WEST:return west?0:1;
        case USA_EAST_WEST:return east?0:west?1:2;
        case USA_WEST_EAST:return west?0:east?1:2;
        default:return world.location==id?0:1;
      }
    }
  }
  public enum Membership {
    ALL("All worlds"),MEMBERS_ONLY("Members only"),F2P_ONLY("F2P only"),MEMBERS_FIRST("Members first"),F2P_FIRST("F2P first");
    final String label;Membership(String label){this.label=label;}@Override public String toString(){return label;}
  }
  public enum ButtonLine {
    CLICK_TO_SWITCH("Off"),GAME_MODE("On");
    final String label;ButtonLine(String label){this.label=label;}@Override public String toString(){return label;}
  }
  public enum FavouriteView {
    WITH_FILTERS("On top"), SEPARATE_COLUMN("Separate");
    final String label;FavouriteView(String label){this.label=label;}@Override public String toString(){return label;}
  }
  final FavouriteView favouriteView;
  final List<Integer> favourites;
  final GameMode mode;final Region region;final Membership membership;
  final boolean compact,showFlag,boldHover,favouritesEnabled;final ButtonLine buttonLine;
  static final WorldPreferences DEFAULT=new WorldPreferences(GameMode.ALL,Region.ALL,Membership.ALL,true,true,ButtonLine.CLICK_TO_SWITCH);
  WorldPreferences(GameMode mode,Region region,Membership membership,boolean compact,boolean showFlag,ButtonLine line){
    this(mode,region,membership,compact,showFlag,line,FavouriteView.WITH_FILTERS,Collections.emptyList(),false,true);
  }
  private WorldPreferences(GameMode mode,Region region,Membership membership,boolean compact,boolean showFlag,ButtonLine line,FavouriteView view,List<Integer> favourites,boolean boldHover,boolean favouritesEnabled){
    this.boldHover=boldHover;this.favouritesEnabled=favouritesEnabled;
    this.favouriteView=view==null?FavouriteView.WITH_FILTERS:view;
    this.favourites=Collections.unmodifiableList(new ArrayList<>(favourites));
    this.mode=mode==null?GameMode.ALL:mode;this.region=region==null?Region.ALL:region;this.membership=membership==null?Membership.ALL:membership;
    this.compact=compact;this.showFlag=showFlag;buttonLine=line==null?ButtonLine.CLICK_TO_SWITCH:line;
  }
  static WorldPreferences from(ClassicWorldSelectorConfig config){
    return config==null?DEFAULT:new WorldPreferences(config.preferredMode(),config.preferredRegion(),config.membership(),config.compact(),config.showFlag(),config.worldInfo()?ButtonLine.GAME_MODE:ButtonLine.CLICK_TO_SWITCH,config.favouriteView(),parseFavourites(config.favouriteWorlds()),config.boldHover(),config.favouritesEnabled());
  }
  WorldPreferences with(String key,Object value){
    return new WorldPreferences(key.equals("preferredMode")?(GameMode)value:mode,key.equals("preferredRegion")?(Region)value:region,
        key.equals("membership")?(Membership)value:membership,key.equals("compact")?(Boolean)value:compact,
        key.equals("showFlag")?(Boolean)value:showFlag,key.equals("buttonLine")?(ButtonLine)value:key.equals("worldInfo")?((Boolean)value?ButtonLine.GAME_MODE:ButtonLine.CLICK_TO_SWITCH):buttonLine,
        key.equals("favouriteView")?(FavouriteView)value:favouriteView,key.equals("favouriteWorlds")?parseFavourites((String)value):favourites,
        key.equals("boldHover")?(Boolean)value:boldHover,key.equals("favouritesEnabled")?(Boolean)value:favouritesEnabled);
  }
  static List<Integer> parseFavourites(String value){
    LinkedHashSet<Integer> ids=new LinkedHashSet<>();
    if(value!=null)for(String part:value.split(","))try{int id=Integer.parseInt(part.trim());if(id>=300&&id<=65535)ids.add(id);}catch(NumberFormatException ignored){}
    return new ArrayList<>(ids);
  }
  String toggleFavourite(int id){
    if(!favouritesEnabled)return serialise(favourites);
    List<Integer> ids=new ArrayList<>(favourites);if(!ids.remove(Integer.valueOf(id)))ids.add(id);return serialise(ids);
  }
  static String serialise(List<Integer> ids){return ids.stream().map(String::valueOf).collect(java.util.stream.Collectors.joining(","));}
  boolean isFavourite(WorldEntry world){return favouritesEnabled&&favourites.contains(world.id);}
  List<WorldEntry> order(List<WorldEntry> source,Comparator<WorldEntry> base){
    List<WorldEntry> result=new ArrayList<>();
    for(WorldEntry world:source){
      if(membership==Membership.MEMBERS_ONLY&&!world.members())continue;
      if(membership==Membership.F2P_ONLY&&world.members())continue;
      result.add(world);
    }
    Comparator<WorldEntry> priority=Comparator.comparingInt((WorldEntry w)->mode==GameMode.ALL||GameMode.of(w.types)==mode?0:1)
        .thenComparingInt(region::rank)
        .thenComparingInt(w->membership==Membership.MEMBERS_FIRST&&!w.members()||membership==Membership.F2P_FIRST&&w.members()?1:0);
    // Preference groups always outrank favourites; the header sort orders each remainder.
    result.sort(priority.thenComparingInt(w->isFavourite(w)?0:1).thenComparing(base));return result;
  }
}

package tv.moonga.classicworlds;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public class BitmapFontTest {
  static ClientBitmapFont fixture(){
    byte[] metrics=new byte[257];Arrays.fill(metrics,(byte)4);metrics[256]=6;
    ClientBitmapFont.Glyph[] glyphs=new ClientBitmapFont.Glyph[256];
    for(int i=0;i<256;i++)glyphs[i]=new ClientBitmapFont.Glyph(3,3,1,2,new int[]{1,0,1,1,1,1,1,0,1});
    return new ClientBitmapFont(metrics,glyphs);
  }
  @Test public void glyphPixelsUseNativeOffsetsAndBaselineExactly(){
    ClientBitmapFont font=fixture();BufferedImage image=new BufferedImage(20,20,BufferedImage.TYPE_INT_ARGB);
    Graphics2D g=image.createGraphics();font.draw(g,"A",3,10,0xffffff,-1);g.dispose();
    assertEquals(0xffffffff,image.getRGB(4,6));assertEquals(0,image.getRGB(5,6));assertEquals(0xffffffff,image.getRGB(6,6));
    assertEquals(0xffffffff,image.getRGB(5,7));assertEquals(0,image.getRGB(4,5));assertEquals(0,image.getRGB(4,9));
    int lit=0;for(int y=0;y<20;y++)for(int x=0;x<20;x++)if(image.getRGB(x,y)!=0)lit++;
    assertEquals(7,lit);
  }
  @Test public void centeringAndSpaceUseAdvanceMetricsRatherThanAwtFontMeasurements(){
    ClientBitmapFont font=fixture();assertEquals(12,font.width("A A"));assertEquals(font.width("A A"),font.width("A\u00a0A"));
    BufferedImage image=new BufferedImage(20,20,BufferedImage.TYPE_INT_ARGB);Graphics2D g=image.createGraphics();font.center(g,"AA",10,10,0xffffff,-1);g.dispose();
    assertEquals(0xffffffff,image.getRGB(7,6));assertEquals(0xffffffff,image.getRGB(11,6));
  }
  @Test public void nativeBlackShadowUsesOnePixelOffset(){
    BufferedImage image=new BufferedImage(20,20,BufferedImage.TYPE_INT_ARGB);Graphics2D g=image.createGraphics();fixture().draw(g,"A",3,10,0xffff00,0);g.dispose();
    assertEquals(0xffffff00,image.getRGB(4,6));assertEquals(0xff000000,image.getRGB(7,9));
  }
  @Test(expected=IllegalArgumentException.class) public void unsupportedMetricsAreRejected(){new ClientBitmapFont(new byte[3],new ClientBitmapFont.Glyph[256]);}
}

